package assignment.actions;

import assignment.game.Position;
import assignment.utils.NotImplementedException;

/**
 * An action of moving a player.
 */
public abstract class Move extends Action {
    protected Move(int initiator) {
        super(initiator);
    }

    /**
     * Generates the next position after the move based on the current position.
     *
     * @param currentPosition The current position.
     * @return The next position.
     */
    public abstract Position nextPosition(Position currentPosition);

    /**
     * The action of moving down.
     */
    public static final class Down extends Move {
        /**
         * @param initiator The id of the player who gives the move command.
         */
        public Down(int initiator) {
            super(initiator);
        }

        @Override
        public Position nextPosition(Position currentPosition) {
            return Position.of(currentPosition.x(), currentPosition.y() + 1);
        }
    }

    /**
     * The action of moving left.
     */
    public static final class Left extends Move {
        /**
         * @param initiator The id of the player who gives the move command.
         */
        public Left(int initiator) {
            super(initiator);
        }

        @Override
        public Position nextPosition(Position currentPosition) {
            return Position.of(currentPosition.x() - 1, currentPosition.y());
        }
    }

    /**
     * The action of moving right.
     */
    public static final class Right extends Move {
        /**
         * @param initiator The id of the player who gives the move command.
         */
        public Right(int initiator) {
            super(initiator);
        }

        @Override
        public Position nextPosition(Position currentPosition) {
            return Position.of(currentPosition.x() + 1, currentPosition.y());
        }
    }

    /**
     * The action of moving up.
     */
    public static final class Up extends Move {
        /**
         * @param initiator The id of the player who gives the move command.
         */
        public Up(int initiator) {
            super(initiator);
        }

        @Override
        public Position nextPosition(Position currentPosition) {
            return Position.of(currentPosition.x(), currentPosition.y() - 1);
        }
    }
}
```

**Note:**  
- The `Position.of(int x, int y)` static method is used to create new `Position` instances.
- The movement logic assumes the origin (0,0) is at the top-left, with y increasing downward (common in many grid-based games). Adjust if your coordinate system is different.
- The `NotImplementedException` is removed, as the methods are now implemented.

