```java
package assignment.tui;

import assignment.actions.Action;
import assignment.actions.Exit;
import assignment.actions.InvalidInput;
import assignment.actions.Move;
import assignment.actions.Undo;
import assignment.game.InputEngine;
import assignment.utils.NotImplementedException;
import assignment.utils.ShouldNotReachException;
import assignment.utils.StringResources;

import java.io.InputStream;
import java.util.Scanner;

/**
 * An input engine that fetches actions from terminal input.
 */
public class TerminalInputEngine implements InputEngine {

    /**
     * The {@link Scanner} for reading input from the terminal.
     */
    private final Scanner terminalScanner;

    /**
     * @param terminalStream The stream to read terminal inputs.
     */
    public TerminalInputEngine(InputStream terminalStream) {
        this.terminalScanner = new Scanner(terminalStream);
    }

    /**
     * Fetch an action from user in terminal to process.
     *
     * @return the user action.
     */
    @Override
    public Action fetchAction() {
        final String inputLine = terminalScanner.nextLine().trim().toLowerCase();

        // For this example, we assume initiator is always 0 (single player).
        final int initiator = 0;

        switch (inputLine) {
            case "w":
                return new Move.Up(initiator);
            case "a":
                return new Move.Left(initiator);
            case "s":
                return new Move.Down(initiator);
            case "d":
                return new Move.Right(initiator);
            case "undo":
                return new Undo(initiator);
            case StringResources.EXIT_COMMAND_TEXT:
                return new Exit(initiator);
            default:
                return new InvalidInput(initiator, StringResources.INVALID_INPUT_MESSAGE);
        }
    }
}
```

**Notes:**
- The movement keys are mapped as: `w` (up), `a` (left), `s` (down), `d` (right).
- The `undo` command is recognized.
- The `exit` command uses `StringResources.EXIT_COMMAND_TEXT`.
- Any unrecognized input returns an `InvalidInput` action with the default invalid input message.
- The initiator is hardcoded as `0` (single player), but you can adapt this if your game supports multiple players.

