/**
 * An input engine that fetches actions from terminal input.
 */
public class TerminalInputEngine implements InputEngine {

    /**
     * The {@link Scanner} for reading input from the terminal.
     */
    private final Scanner terminalScanner;

    /**
     * @param terminalStream The stream to read terminal inputs.
     */
    public TerminalInputEngine(InputStream terminalStream) {
        this.terminalScanner = new Scanner(terminalStream);
    }

    /**
     * Fetch an action from user in terminal to process.
     *
     * @return the user action.
     */
    @Override
    public Action fetchAction() {
        final String inputLine = terminalScanner.nextLine().trim().toLowerCase();

        // For this implementation, we assume initiator is always 0 (single player).
        final int initiator = 0;

        // Exit command
        if (inputLine.equals(StringResources.EXIT_COMMAND_TEXT)) {
            return new Exit(initiator);
        }

        // Undo command
        if (inputLine.equals("undo")) {
            return new Undo(initiator);
        }

        // Move commands: w (up), a (left), s (down), d (right)
        switch (inputLine) {
            case "w":
                return new Move.Up(initiator);
            case "a":
                return new Move.Left(initiator);
            case "s":
                return new Move.Down(initiator);
            case "d":
                return new Move.Right(initiator);
        }

        // Invalid input
        return new InvalidInput(initiator, StringResources.INVALID_INPUT_MESSAGE);
    }
}
